import { useState } from "react";
import { Activity, ArrowUpRight, Check, Circle, CircleDot, Layers, Network } from "lucide-react";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Scatter, ScatterChart, Tooltip, XAxis, YAxis } from "recharts";
import { Section, Segmented } from "./primitives";
import { trend } from "./fixtures";

const chartColors = ["var(--azs-action)", "var(--azs-success)", "var(--azs-warning)"];
const distribution = [{ name: "Atmosphere", value: 42 }, { name: "Structure", value: 35 }, { name: "Archive", value: 23 }];
const scatter = Array.from({ length: 18 }, (_, index) => ({ altitude: 12 + index * 4, clarity: 20 + index * 3 + (index % 4) * 8 }));
const nodes = [{ id: "Source", left: 18, top: 47 }, { id: "Cirrus", left: 48, top: 20 }, { id: "Stratus", left: 49, top: 70 }, { id: "Archive", left: 81, top: 46 }];
const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

export default function Visualizations() {
  const [chart, setChart] = useState("Area");
  const [upper, setUpper] = useState(true);
  const [lower, setLower] = useState(true);
  const [cell, setCell] = useState("Wed / 12:00 / 79 samples");
  const [node, setNode] = useState("Source");
  const [step, setStep] = useState(2);
  const axis = { tick: { fill: "var(--azs-steel)", fontSize: 11 }, axisLine: false, tickLine: false };
  const shared = <><CartesianGrid stroke="var(--azs-line)" strokeDasharray="3 5" vertical={false} /><XAxis dataKey="time" {...axis} minTickGap={30} /><YAxis {...axis} width={32} /><Tooltip contentStyle={{ border: "1px solid var(--azs-control)", borderRadius: 4, fontSize: 12, color: "var(--azs-ink)", background: "var(--azs-porcelain)" }} /></>;
  return <Section id="charts" index="04" title="Patterns across the horizon" trailing={<span className="azs-section-tag"><Activity size={14} /> Visualizations</span>}>
    <div className="azs-chart-main"><div className="azs-chart-heading"><div><span className="azs-eyebrow azs-muted">OBSERVATION VOLUME / SYNTHETIC</span><h3>Two layers. One perspective.</h3></div><Segmented label="Chart type" options={["Area", "Line", "Bars"]} value={chart} onChange={setChart} /></div><div className="azs-chart-legend"><label className="azs-check"><input type="checkbox" checked={upper} onChange={() => setUpper(value => !value)} /><span className="azs-legend-stroke" />Upper layer</label><label className="azs-check"><input type="checkbox" checked={lower} onChange={() => setLower(value => !value)} /><span className="azs-legend-stroke azs-legend-dashed" />Lower layer</label><span className="azs-mono azs-muted">SAMPLES / HOUR</span></div><div className="azs-chart-canvas" role="group" aria-label={`${chart} chart of synthetic observation volume`}>
      <ResponsiveContainer width="100%" height="100%">{chart === "Area" ? <AreaChart data={trend} margin={{ left: 0, right: 12, top: 12, bottom: 0 }}>{shared}{upper && <Area type="monotone" dataKey="upper" name="Upper layer" stroke="var(--azs-action)" fill="var(--azs-sky)" fillOpacity={0.22} strokeWidth={2.5} isAnimationActive={false} />}{lower && <Area type="monotone" dataKey="lower" name="Lower layer" stroke="var(--azs-success)" fill="var(--azs-success)" fillOpacity={0.08} strokeDasharray="5 4" strokeWidth={2} isAnimationActive={false} />}</AreaChart> : chart === "Line" ? <LineChart data={trend} margin={{ left: 0, right: 12, top: 12, bottom: 0 }}>{shared}{upper && <Line type="monotone" dataKey="upper" name="Upper layer" stroke="var(--azs-action)" strokeWidth={2.5} dot={{ r: 3 }} isAnimationActive={false} />}{lower && <Line type="monotone" dataKey="lower" name="Lower layer" stroke="var(--azs-success)" strokeDasharray="5 4" strokeWidth={2} dot={{ r: 3 }} isAnimationActive={false} />}</LineChart> : <BarChart data={trend} margin={{ left: 0, right: 12, top: 12, bottom: 0 }}>{shared}{upper && <Bar dataKey="upper" name="Upper layer" fill="var(--azs-action)" radius={[2, 2, 0, 0]} isAnimationActive={false} />}{lower && <Bar dataKey="lower" name="Lower layer" fill="var(--azs-success)" radius={[2, 2, 0, 0]} isAnimationActive={false} />}</BarChart>}</ResponsiveContainer>
    </div><details className="azs-chart-data"><summary>Observation values</summary><div className="azs-chart-data-values">{trend.map(point => <span key={point.time}><strong>{point.time}</strong> {point.upper} / {point.lower}</span>)}</div></details></div>
    <div className="azs-chart-grid"><div className="azs-chart-small"><div className="azs-subheading"><h3>Composition</h3><Layers size={17} /></div><div className="azs-donut-layout"><div className="azs-donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={distribution} dataKey="value" innerRadius="60%" outerRadius="85%" paddingAngle={4} stroke="none" isAnimationActive={false}>{distribution.map((item, index) => <Cell key={item.name} fill={chartColors[index]} />)}</Pie></PieChart></ResponsiveContainer><span><strong>100</strong><small>samples</small></span></div><ul className="azs-chart-key">{distribution.map((item, index) => <li key={item.name}><span style={{ background: chartColors[index] }} /><span>{item.name}</span><strong>{item.value}%</strong></li>)}</ul></div></div>
    <div className="azs-chart-small"><div className="azs-subheading"><h3>Altitude / clarity</h3><ArrowUpRight size={17} /></div><div className="azs-mini-chart" role="img" aria-label="Synthetic scatter plot: clarity generally rises with altitude"><ResponsiveContainer width="100%" height="100%"><ScatterChart margin={{ right: 12 }}><CartesianGrid stroke="var(--azs-line)" strokeDasharray="3 5" /><XAxis type="number" dataKey="altitude" {...axis} /><YAxis type="number" dataKey="clarity" {...axis} width={30} /><Tooltip contentStyle={{ background: "var(--azs-porcelain)", border: "1px solid var(--azs-control)", fontSize: 12 }} cursor={{ strokeDasharray: "3 3" }} /><Scatter name="Reference points" data={scatter} fill="var(--azs-action)" isAnimationActive={false} /></ScatterChart></ResponsiveContainer></div><span className="azs-mono azs-muted">18 FIXTURE POINTS / ARBITRARY UNITS</span></div>
    <div className="azs-chart-small"><div className="azs-subheading"><h3>Relationships</h3><Network size={17} /></div><div className="azs-network" aria-label="Reference relationships"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M18 47 L48 20 L81 46 L49 70 Z M48 20 L49 70" fill="none" stroke="var(--azs-control)" strokeWidth=".5" strokeDasharray="2 2" /></svg>{nodes.map(item => <button key={item.id} className="azs-network-node" style={{ left: `${item.left}%`, top: `${item.top}%` }} aria-pressed={node === item.id} onClick={() => setNode(item.id)}><CircleDot size={22} /><span>{item.id}</span></button>)}</div><p className="azs-network-detail"><Circle size={12} />{node} / {node === "Source" || node === "Archive" ? "2" : "3"} connections</p></div></div>
    <div className="azs-heatmap-layout"><div><div className="azs-subheading"><h3>A week in fragments</h3><span className="azs-mono">SAMPLE DENSITY</span></div><div className="azs-heatmap" aria-label="Synthetic weekly sample density">{days.map((day, dayIndex) => <div className="azs-heatmap-row" key={day}><span className="azs-mono">{day}</span>{Array.from({ length: 12 }, (_, hour) => { const count = ((dayIndex * 17 + hour * 23 + 7) % 100); return <button type="button" key={hour} aria-label={`${day} ${String(hour * 2).padStart(2, "0")}:00 ${count} samples`} style={{ background: ["#dceaff", "#accded", "#72a7db", "#3376bc", "#123f91"][Math.floor(count / 20)] }} onClick={() => setCell(`${day} / ${String(hour * 2).padStart(2, "0")}:00 / ${count} samples`)} />; })}</div>)}</div><div className="azs-row azs-between azs-heatmap-caption"><span className="azs-mono">{cell}</span><span className="azs-mono azs-muted">00:00 - 22:00 UTC</span></div></div><div className="azs-timeline"><div className="azs-subheading"><h3>Collection journey</h3><span className="azs-mono">AS-001</span></div><ol>{[{ title: "Source received", time: "09:12 UTC" }, { title: "Structure verified", time: "09:18 UTC" }, { title: "Review in progress", time: "09:42 UTC" }, { title: "Archive prepared", time: "Pending" }].map((item, index) => <li key={item.title} data-complete={index < step} data-current={index === step}><button aria-label={`View stage ${index + 1}: ${item.title}`} onClick={() => setStep(index)}><span className="azs-timeline-dot">{index < step ? <Check size={12} /> : index + 1}</span><span><strong>{item.title}</strong><small>{item.time}</small></span></button></li>)}</ol></div></div>
  </Section>;
}